-- No prices or classifications are inferred for the existing catalog.
ALTER TABLE "Producto" ADD COLUMN "pvpMaximo" DECIMAL CHECK("pvpMaximo" IS NULL OR ("pvpMaximo">0 AND "pvpMaximo"<=100000 AND abs("pvpMaximo"*100-round("pvpMaximo"*100))<0.000001));
CREATE TRIGGER "Producto_pvp_insert" BEFORE INSERT ON "Producto" WHEN (NEW."pvpMaximo" IS NOT NULL AND NEW."precio">NEW."pvpMaximo") OR (NEW."tipoProducto"='medicamento' AND (NEW."pvpMaximo" IS NULL OR NEW."registroSanitario" IS NULL OR length(trim(NEW."registroSanitario"))=0 OR NEW."laboratorio" IS NULL OR length(trim(NEW."laboratorio"))=0 OR NEW."presentacion" IS NULL OR length(trim(NEW."presentacion"))=0)) BEGIN SELECT RAISE(ABORT,'El medicamento requiere PVP, registro sanitario, laboratorio y presentación; precio no debe superar PVP.'); END;
CREATE TRIGGER "Producto_pvp_update" BEFORE UPDATE ON "Producto" WHEN (NEW."pvpMaximo" IS NOT NULL AND NEW."precio">NEW."pvpMaximo") OR (NEW."tipoProducto"='medicamento' AND (NEW."pvpMaximo" IS NULL OR NEW."registroSanitario" IS NULL OR length(trim(NEW."registroSanitario"))=0 OR NEW."laboratorio" IS NULL OR length(trim(NEW."laboratorio"))=0 OR NEW."presentacion" IS NULL OR length(trim(NEW."presentacion"))=0)) BEGIN SELECT RAISE(ABORT,'El medicamento requiere PVP, registro sanitario, laboratorio y presentación; precio no debe superar PVP.'); END;
CREATE TRIGGER "Proveedor_ruc_insert" BEFORE INSERT ON "Proveedor" WHEN substr(NEW."ruc",11)!='001' OR cast(substr(NEW."ruc",1,10) AS INTEGER)%1111111111=0 BEGIN SELECT RAISE(ABORT,'Formato de RUC ecuatoriano inválido.'); END;
CREATE TRIGGER "Proveedor_ruc_update" BEFORE UPDATE ON "Proveedor" WHEN substr(NEW."ruc",11)!='001' OR cast(substr(NEW."ruc",1,10) AS INTEGER)%1111111111=0 BEGIN SELECT RAISE(ABORT,'Formato de RUC ecuatoriano inválido.'); END;
